/**
 * The Spanish dictionary — deliberately its own module, and deliberately never imported statically.
 *
 * It is ~325 KB of string literals. Compiled into the entry chunk beside English (which is where it
 * lived until now) that is a third of a megabyte parsed, evaluated and held resident on every
 * launch, of which one of the two dictionaries is, by definition, never read. `translations.ts`
 * pulls this in with a dynamic `import()` when — and only when — the stored language is `es`.
 *
 * `satisfies` rather than `as const`: it keeps the compile-time guarantee that matters (every key
 * English has, Spanish has, with a string for it) without asking TypeScript to widen 4,800 literal
 * types nothing reads.
 */
import type { TranslationKey } from "./translations";

