  "settings.gitlabHint":
    "Un token de acceso personal de GitLab con el scope `api`. Se guarda en el almacén de credenciales del sistema operativo, nunca en un archivo. Un token por instancia — gitlab.com y cualquier GitLab autogestionado pueden estar conectados a la vez.",
  "settings.gitlabHostLabel": "Host de GitLab",
  "settings.gitlabHostHint": "Déjalo en gitlab.com, o escribe el host de tu GitLab autogestionado (ej. git.miempresa.com).",
  "settings.jiraHint":
    "Un sitio de Jira más el correo de la cuenta y el token de API que le corresponden — Jira autentica el par, así que el correo es obligatorio. Solo el token llega al llavero del sistema. Sirve para publicar un backlog y para revisar una incidencia que ya existe; Jira no aloja código, así que no aparece en la parte de pull requests.",
  "settings.jiraSite": "Sitio (p. ej. acme.atlassian.net)",
  "settings.jiraEmail": "Correo de la cuenta",
  "settings.jiraToken": "Token de API",
  "settings.mondayHint":
    "Un token personal de API de monday.com (Perfil → Developers → My access tokens). No hay nada más que rellenar: todas las cuentas usan la misma dirección de API, así que el token es lo que identifica la cuenta — CodeFlow le pregunta a monday de quién es al guardarlo. Sirve para publicar un backlog y para revisar un elemento que ya existe; monday no aloja código, así que no aparece en la parte de pull requests.",
  "settings.mondayToken": "Token de API",
