  "task.notes": "Escribir en una nota",
  "task.notesHint": "Escribe Markdown en la nota abierta desde el botón de IA del editor. Solo texto y sin repositorio, así que puede ir a cualquier proveedor.",
  "task.diagram": "Dibujar un diagrama",
