  "task.workItemReview": "Revisar · work items",
  "task.workItemReviewHint":
    "Analiza un work item y reescribe su descripción, criterios y tareas contra el código. Lee archivos, así que necesita un motor con herramientas.",
  "task.wiki": "Wiki · documentación",
  "task.wikiHint":
    "Lee un repositorio y escribe su documentación técnica. Es la ejecución más larga de la app, y necesita un motor con herramientas.",
  "settings.localProviderNote":
    "Este motor solo completa texto: cubre mensajes de commit, descripciones de PR, análisis, review y resolución de conflictos. Todo lo que necesite ejecutar herramientas (Corregir con IA, MCP) requiere un motor agente — para modelos locales, ese motor es Cline.",
  "settings.baseModel": "Modelo base",
  "settings.baseModelHint": "Lo usa el chat y es el valor por defecto de las tareas de abajo.",
  "settings.localModel": "Modelo local",
  "settings.claudeTitle": "Claude Code (headless)",
  "settings.claudeHint":
    "CodeFlow invoca a Claude Code en modo headless para revisar pull requests usando tu suscripción actual — esta configuración controla cómo se lanza.",
  "settings.claudeBinaryLabel": "Ruta al binario de claude",
  "settings.claudeBinaryHint": "Déjalo como claude si ya está en tu PATH.",
  "settings.selectClaudeBinaryTitle": "Selecciona el binario",
  "settings.browse": "Examinar",
  "settings.model": "Modelo",
  "settings.modelDefault": "Predeterminado del CLI (recomendado)",
  "settings.modelCustom": "ID de modelo personalizado…",
  "settings.modelIdHintRun": "Lista los IDs disponibles con",
  "settings.modelIdHintClaude": "Usa un alias — sonnet, opus o haiku — o un ID completo de la doc de Anthropic.",
  "settings.modelIdHintGeneric": "Ingresa el ID exacto que acepta el CLI.",
  "settings.modelIdPlaceholder": "ID de modelo",
  "settings.allowedTools": "Herramientas permitidas",
  "settings.allowedToolsHint":
    "Herramientas que este motor puede usar — al revisar y analizar, y en los turnos de cada tarea de agente y cada paso de cadena que corra en él. Para trabajo de solo lectura bastan las básicas.",
  "settings.toolsUnrestricted":
    "Sin restricción: el motor corre con todas sus herramientas, incluidas las que use para lanzar subagentes. Si marcas una casilla, solo se permite lo marcado — también en los turnos de agente, así que deja Edit y Write si tus agentes modifican archivos.",
  "settings.toolsUseRecommended": "Usar el conjunto recomendado",
  "settings.toolsNoRead":
    "Esta lista no tiene Read, así que el motor no puede abrir ni un archivo — responderá sobre un repositorio que nunca vio. La lista rige las revisiones, los análisis y cada turno de agente en este motor.",
  "settings.toolsAddRecommended": "Añadir las básicas",
  "settings.toolsClearRestriction": "Quitar la restricción (todas las herramientas)",
  "settings.toolsSandboxNote":
    "Este CLI no admite lista de herramientas. Lo que puede tocar lo decide su propio modo de permisos, que CodeFlow ajusta según la acción: solo lectura para revisar y analizar, y escritura únicamente en las acciones que modifican archivos.",
  "settings.toolReadDesc": "Lee el contenido de archivos del repositorio",
  "settings.toolTaskDesc":
    "Lanza subagentes que trabajan en paralelo dentro de un mismo turno. Comparten la copia de trabajo de este paso, así que sirve para leer (un revisor por varias áreas) y no para escribir. CodeFlow no los ve: no son pasos, no tienen verificación y su coste cae sobre el paso que los lanzó.",
  "settings.toolGrepDesc": "Busca contenido dentro de archivos",
  "settings.toolGlobDesc": "Busca archivos por patrón de nombre",
  "settings.toolWebFetchDesc": "Obtiene el contenido de una URL (ej. documentación o specs enlazadas)",
  "settings.toolWebSearchDesc": "Busca en la web",
  "settings.toolBashDesc": "Ejecuta comandos de shell (linters, tests…) — acceso amplio, actívalo con cuidado",
  "settings.toolEditDesc": "Modifica archivos existentes — no se necesita para una revisión de solo lectura",
  "settings.toolWriteDesc": "Crea archivos nuevos — no se necesita para una revisión de solo lectura",
  "settings.toolNotebookEditDesc": "Edita celdas de notebooks Jupyter",
  "settings.addCustomTool": "Agrega el nombre de una herramienta personalizada (ej. una herramienta MCP)",
  "settings.add": "Agregar",
  "settings.commitTemplateHint":
    "La instrucción que se envía a tu proveedor de IA activo al generar un mensaje de commit desde tu diff en stage. Personalízala para restringir qué tipos de Conventional Commits debe usar, forzar un scope, o seguir la convención de tu equipo.",
  "settings.reviewTemplateHint":
    "La instrucción que se envía a tu proveedor de IA activo al revisar el diff de un pull request. Controla el formato de cada hallazgo (severidad, por qué, sugerencia, ejemplo de solución, confianza) — el modelo, la fecha y el pie de \"revisión automatizada\" siempre los agrega CodeFlow, no este prompt.",
  "settings.analyzeTemplateHint":
    "La instrucción que se envía a tu proveedor de IA activo con el botón \"Analizar cambios\" de la pestaña Changes, revisando tu diff sin commitear en busca de bugs y vulnerabilidades antes de comitear. Usa el mismo formato de hallazgos que la plantilla de revisión de PR.",
